import { useState, useEffect, useRef, FC, FormEvent, MouseEvent } from 'react';
import { GeminiService } from '../services/geminiService';
import { Location, RouteResponse, MapPoint, SavedRoute, OptimizedAlternative, TravelStats } from '../types';

declare const L: any;

const FormattedAnalysis: FC<{ text: string }> = ({ text }) => {
  const lines = text.split('\n');

  return (
    <div className="space-y-4 break-words overflow-hidden w-full">
      {lines.map((line, idx) => {
        const trimmed = line.trim();
        if (!trimmed) return <div key={idx} className="h-1" />;

        if (trimmed.startsWith('###')) {
          const headerText = trimmed.replace(/^###\s*/, '');
          const isEnforcement = headerText.includes('ENFORCEMENT');
          const isNav = headerText.includes('NAVIGATIONAL') || headerText.includes('STEPS');

          return (
            <h4 key={idx} className={`text-[10px] font-black uppercase tracking-[0.25em] mt-6 border-b pb-2 flex items-center gap-3 ${
              isEnforcement ? 'text-blue-500 border-blue-500/20' : 
              isNav ? 'text-emerald-500 border-emerald-500/20' :
              'text-amber-500 border-amber-500/10'
            }`}>
              <span className="w-1.5 h-1.5 rounded-full bg-current animate-pulse"></span>
              {headerText}
            </h4>
          );
        }

        const numMatch = trimmed.match(/^(\d+)\.\s+(.*)/);
        if (numMatch) {
          return (
            <div key={idx} className="flex gap-4 items-start group">
              <span className="flex-shrink-0 w-6 h-6 rounded-lg bg-slate-900 border border-slate-800 text-amber-500 text-[10px] font-black flex items-center justify-center mt-0.5 shadow-lg group-hover:border-amber-500/50 transition-colors">
                {numMatch[1]}
              </span>
              <p className="text-[12px] leading-relaxed text-slate-300 font-medium">
                {numMatch[2]}
              </p>
            </div>
          );
        }

        if (trimmed.startsWith('•') || trimmed.startsWith('-') || trimmed.startsWith('*')) {
          const isConstruction = trimmed.toLowerCase().includes('construction') || trimmed.toLowerCase().includes('work');
          const isAccident = trimmed.toLowerCase().includes('accident') || trimmed.toLowerCase().includes('crash');

          return (
            <div key={idx} className={`flex gap-3 items-start pl-2 p-2 rounded-lg border transition-colors ${
              isConstruction ? 'bg-orange-500/5 border-orange-500/10' :
              isAccident ? 'bg-rose-500/5 border-rose-500/10' :
              'border-transparent'
            }`}>
              <span className={`mt-1.5 flex-shrink-0 w-1.5 h-1.5 rounded-full ${
                isConstruction ? 'bg-orange-500' :
                isAccident ? 'bg-rose-500' :
                'bg-amber-500'
              }`}></span>
              <p className="text-[11px] leading-relaxed text-slate-400">
                {trimmed.replace(/^[•\-*]\s*/, '')}
              </p>
            </div>
          );
        }

        return (
          <p key={idx} className="text-[11px] leading-relaxed text-slate-400 pl-2">
            {trimmed}
          </p>
        );
      })}
    </div>
  );
};

const Dashboard: FC = () => {
  const [origin, setOrigin] = useState('Denver International Airport');
  const [destination, setDestination] = useState('Downtown Denver');
  const [loading, setLoading] = useState(false);
