4. **LOCAL SPECIFICITY**: Always ground your advice in Colorado law and Denver-specific court procedures.

CONSULTATION REQUEST: "${query}"
${partyName ? `Party focus: ${partyName}` : ''}
${caseNumber ? `Case ID: ${caseNumber}` : ''}
${jurisdiction ? `Jurisdiction: ${jurisdiction}` : ''}

STRUCTURE YOUR RESPONSE:
# Legal Consultation Brief
## Summary of Strategic Position
## Procedural Considerations
## Recommended Actions (Formal list)
## Risks and Disclaimers`;
};

const generateStrategicTelemetry = async (query: string, summary: string): Promise<StrategicTelemetry> => {
    const prompt = `Analyze the following case profile and provide a formal Readiness Assessment and Risk Profile.
    Case Context: ${summary.substring(0, 2000)}

    Output JSON with:
    - readinessScore (0-100)
    - complexityIndex (1-10)
    - strategicFactors (Object: evidence, procedural, jurisdictional, resource, opponentVulnerability 1-10)
    - threatMatrix (Array of 5: label, impact 1-10, probability 1-10)`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
            }
        });
        return safeParseJSON<StrategicTelemetry>(response.text) || { 
          readinessScore: 50, 
          complexityIndex: 5, 
          threatMatrix: [],
          strategicFactors: { evidence: 5, procedural: 5, jurisdictional: 5, resource: 5, opponentVulnerability: 5 }
        };
    } catch {
        return { 
          readinessScore: 50, 
          complexityIndex: 5, 
          threatMatrix: [],
          strategicFactors: { evidence: 5, procedural: 5, jurisdictional: 5, resource: 5, opponentVulnerability: 5 }
        };
    }
};

const generateAdversarialStrategy = async (query: string, summary: string): Promise<AdversarialStrategy> => {
    const prompt = `Perform a formal Adversarial Analysis. Predict opposing counsel moves and propose strategic defensive counters.
    Context: ${summary.substring(0, 2000)}

    Output JSON: { prosecutorMoves: [], defenseCounters: [], hiddenRisks: [] } (3 items each)`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 8192 },
                responseMimeType: "application/json"
            }
        });
        return safeParseJSON<AdversarialStrategy>(response.text) || { prosecutorMoves: [], defenseCounters: [], hiddenRisks: [] };
    } catch {
        return { prosecutorMoves: [], defenseCounters: [], hiddenRisks: [] };
    }
}

export const generateExecutiveSummary = async (summary: string, strategy: AdversarialStrategy): Promise<string> => {
    const prompt = `Condense the following legal analysis into a ultra-concise Executive Summary (max 200 words).
    Highlight:
    1. Most critical finding.
    2. Primary tactical recommendation.
    3. High-level strategic outlook.

    Use a professional, calm, senior-partner tone.
    Context: ${summary}
    Strategy Context: ${JSON.stringify(strategy)}`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 4096 }
            }
        });
        return response.text || "Summary synthesis failure.";
    } catch {
        return "Executive brief synthesis interrupted.";
    }
};

const extractTimelineEvents = async (summary: string): Promise<TimelineEvent[]> => {
  const prompt = `Identify significant procedural milestones and dates from this brief. Output JSON: { events: [{ date, description, type, citation }] }. Types: filing, motion, court_date, ruling, other.`;
  try {
      const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview', 
          contents: prompt + "\nContext: " + summary.substring(0, 4000),
          config: { responseMimeType: "application/json" }
      });
      const parsed = safeParseJSON<{ events: TimelineEvent[] }>(parsed.text);
      return parsed?.events || [];
  } catch { return []; }
};

const extractJudges = async (summary: string): Promise<JudgeSummary[]> => {
    const prompt = `List any Judicial Officers identified in this text. JSON: { judges: [{ name }] }.`;
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt + "\nContext: " + summary.substring(0, 2000),
            config: { responseMimeType: "application/json" }
        });
        const parsed = safeParseJSON<{ judges: JudgeSummary[] }>(response.text);
        return parsed?.judges || [];
    } catch { return []; }
};

export const searchWebWithGemini = async (params: SearchParams, onPartial: (partial: any) => void): Promise<SearchResult> => {
    const prompt = buildPrompt(params);
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
            tools: [{ googleSearch: {} }],
            thinkingConfig: { thinkingBudget: 16384 }
        }
    });

    const summary = response.text || "No intelligence synthesized.";
    const sources: Source[] = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
        uri: chunk.web?.uri || '',
        title: chunk.web?.title || 'Legal Reference'
    })).filter((s: any) => s.uri) || [];

    onPartial({ summary, sources });

    const [telemetry, adversarial, timeline, judges] = await Promise.all([
        generateStrategicTelemetry(params.query, summary),
        generateAdversarialStrategy(params.query, summary),
        extractTimelineEvents(summary),
        extractJudges(summary)
    ]);

    return {
        summary,
        sources,
        telemetry,
        adversarialStrategy: adversarial,
        timelineEvents: timeline,
        identifiedJudges: judges,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false
    };
};

