import React, { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { type SearchResult, type SearchParams } from '../types';
import { generateExecutiveSummary } from '../services/geminiService';
import FollowUpQuestions from './FollowUpQuestions';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import RelatedQueries from './RelatedQueries';
import TimelineChart from './TimelineChart';
import IdentifiedJudges from './IdentifiedJudges';
import AdversarialStrategyWidget from './AdversarialStrategyWidget';
import StrategicTelemetryWidget from './StrategicTelemetryWidget';
import SpinnerIcon from './icons/SpinnerIcon';
import SparklesIcon from './icons/SparklesIcon';

interface ResultsDisplayProps {
  output: SearchResult | null;
  searchParams: SearchParams | null;
  isLoading: boolean;
  onQuestionClick: (q: string) => void;
  onAnalysisClick: (p: string) => void;
  onSave: (p: SearchParams, r: SearchResult) => void;
  onRemoveSave: (p: SearchParams) => void;
  isSaved: boolean;
  onJudgeClick: (n: string) => void;
}

export default function ResultsDisplay({ output, searchParams, isLoading, onQuestionClick, onSave, onRemoveSave, isSaved, onJudgeClick }: ResultsDisplayProps): React.ReactNode {
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [execSummary, setExecSummary] = useState<string | null>(null);

  const handleSummarize = async () => {
    if (!output) return;
    setIsSummarizing(true);
    try {
      const summary = await generateExecutiveSummary(output.summary, output.adversarialStrategy!);
      setExecSummary(summary);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSummarizing(false);
    }
  };

  if (!output && !isLoading) return null;

  return (
    <div className="flex flex-col gap-10 pb-20 fade-entry">
      {isLoading && (!output || !output.summary) ? (
        <div className="law-card p-20 flex flex-col items-center justify-center gap-6">
          <div className="w-12 h-12 border-2 border-blue-500/20 border-t-blue-500 rounded-full animate-spin"></div>
          <span className="etched-label animate-pulse">Establishing Neural Link to Court Records...</span>
        </div>
      ) : output ? (
        <div className="flex flex-col gap-10">

          {/* Main Action Bar */}
          <div className="flex justify-end gap-3 px-1">
             <button 
                onClick={handleSummarize}
                disabled={isSummarizing || !!execSummary}
                className="flex items-center gap-3 px-6 py-3 bg-white/5 border border-white/10 rounded-lg text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:border-blue-500/40 hover:text-white transition-all disabled:opacity-50"
             >
                {isSummarizing ? <SpinnerIcon className="w-3 h-3 animate-spin" /> : <SparklesIcon className="w-3 h-3" />}
                {execSummary ? 'Brief Synthesized' : 'Summarize Brief'}
             </button>
          </div>

          {/* Executive Summary Section */}
          {execSummary && (
            <div className="law-card border-accent-gold/20 bg-accent-gold/[0.03] p-10 lg:p-12 animate-in slide-in-from-top-4 duration-500">
               <div className="flex items-center gap-4 mb-8">
                  <div className="w-1.5 h-1.5 rounded-full bg-accent-gold shadow-[0_0_10px_#c5a059]"></div>
                  <h3 className="etched-label text-accent-gold">Executive Summary Dossier</h3>
               </div>
               <div className="text-xl lg:text-2xl text-slate-200 serif-heading italic leading-relaxed font-light">
                  {execSummary}
               </div>
               <div className="mt-8 pt-8 border-t border-accent-gold/10 flex justify-between items-center">
                  <span className="text-[9px] font-bold text-slate-600 uppercase tracking-widest">Counsel Signature // v1.02</span>
                  <div className="h-px flex-grow mx-8 bg-accent-gold/10"></div>
                  <div className="w-24 h-6 opacity-20 filter grayscale invert">
                     <svg viewBox="0 0 100 20" className="w-full h-full"><path d="M0,15 Q25,5 50,15 T100,15" fill="none" stroke="currentColor" strokeWidth="2" /></svg>
                  </div>
               </div>
            </div>
          )}

          <div className="law-card bg-slate-900 border-white/5 p-8 lg:p-16 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-1/3 h-full bg-gradient-to-l from-blue-500/[0.02] to-transparent pointer-events-none"></div>

            <div className="flex flex-col md:flex-row justify-between items-start border-b border-white/5 pb-10 mb-10 gap-6">
              <div className="space-y-3">
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                  <span className="etched-label text-[10px]">Case Counsel Report #{(Math.random() * 10000).toFixed(0)}</span>
                </div>
                <h2 className="text-3xl lg:text-5xl font-bold text-white tracking-tight serif-heading leading-tight">
                  Strategic Briefing
                </h2>
              </div>
              <button 
                onClick={() => isSaved ? onRemoveSave(searchParams!) : onSave(searchParams!, output)} 
                className={`p-4 rounded border transition-all ${isSaved ? 'bg-blue-600 text-white border-blue-500' : 'bg-slate-800 text-slate-500 border-slate-700 hover:text-white'}`}
              >
                {isSaved ? <BookmarkFilledIcon className="w-5 h-5" /> : <BookmarkIcon className="w-5 h-5" />}
              </button>
            </div>

            <div className="prose prose-invert prose-lg lg:prose-xl max-w-none text-slate-300
              prose-h1:serif-heading prose-h1:text-white prose-h1:text-3xl prose-h1:mt-12
              prose-h2:etched-label prose-h2:text-blue-500/80 prose-h2:mt-12 prose-h2:mb-6 prose-h2:border-b prose-h2:border-white/5 prose-h2:pb-3
              prose-p:leading-relaxed prose-p:font-light
              prose-strong:text-white prose-strong:font-bold
              prose-li:text-slate-400">
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <StrategicTelemetryWidget telemetry={output.telemetry} isLoading={false} />
            <AdversarialStrategyWidget strategy={output.adversarialStrategy} isLoading={false} />
          </div>

          <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
            {output.identifiedJudges && output.identifiedJudges.length > 0 && (
              <IdentifiedJudges judges={output.identifiedJudges} isLoading={false} onJudgeClick={onJudgeClick} />
            )}
            <div className="law-card p-10 bg-slate-900/50">
              <h4 className="etched-label mb-8">Verified Sources</h4>
              <div className="space-y-3">
                {output.sources.map((s, i) => (
                  <a key={i} href={s.uri} target="_blank" rel="noreferrer" className="flex items-center justify-between p-4 bg-slate-950/40 border border-white/5 rounded hover:border-blue-500/30 transition-all group">
                    <span className="text-xs font-medium text-slate-400 group-hover:text-white truncate">{s.title}</span>
                    <span className="text-[10px] text-blue-500 font-bold opacity-0 group-hover:opacity-100 transition-all">View Record</span>
                  </a>
                ))}
              </div>
            </div>
          </div>

          {output.timelineEvents && output.timelineEvents.length > 0 && (
            <div className="law-card p-10 lg:p-16">
              <TimelineChart events={output.timelineEvents} isLoading={false} />
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <FollowUpQuestions questions={output.followUpQuestions || []} onQuestionClick={onQuestionClick} />
            <RelatedQueries queries={output.relatedQueries || []} onQueryClick={onQuestionClick} />
          </div>
        </div>
      ) : null}
    </div>
  );
}

