import Banner from './components/Banner';
import SearchForm from './components/SearchForm';
import ResultsDisplay from './components/ResultsDisplay';
import Examples from './components/Examples';
import Bookmarks from './components/Bookmarks';
import JudgeDetailModal from './components/JudgeDetailModal';
import CrossReferenceModal from './components/CrossReferenceModal';
import NarrativeMapper from './components/NarrativeMapper';
import DocumentWorkspace from './components/DocumentWorkspace';
import BrainCircuitIcon from './components/icons/BrainCircuitIcon';
import BookmarkIcon from './components/icons/BookmarkIcon';
import HistoryIcon from './components/icons/HistoryIcon';

type AppTab = 'copilot' | 'audit' | 'vault';

export default function App(): React.ReactNode {
  const [activeTab, setActiveTab] = useState<AppTab>('copilot');
  const [searchParams, setSearchParams] = useState<SearchParams>({
    query: '',
    searchType: SearchType.SEARCH,
    listCount: undefined,
    dateRange: DateRange.ANY,
    siteRestrict: '',
    fileType: '',
    partyName: '',
    caseNumber: '',
    caseStatus: CaseStatus.ALL,
    caseType: CaseType.ALL,
    jurisdiction: Jurisdiction.ALL,
  });
  const [currentSearchParamsForResults, setCurrentSearchParamsForResults] = useState<SearchParams | null>(null);
  const [output, setOutput] = useState<SearchResult | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  const [showJudgeModal, setShowJudgeModal] = useState(false);
  const [selectedJudgeName, setSelectedJudgeName] = useState<string | null>(null);

  const [documentWorkspaceFiles, setDocumentWorkspaceFiles] = useState<DocumentAnalysisResult[]>([]);
  const [activeWorkspaceFileId, setActiveWorkspaceFileId] = useState<string | null>(null);

  const [showCrossRefModal, setShowCrossRefModal] = useState(false);
  const [crossRefResult, setCrossRefResult] = useState<CrossReferenceResult | null>(null);
  const [isCrossRefLoading, setIsCrossRefLoading] = useState(false);

  const [showNarrativeMapper, setShowNarrativeMapper] = useState(false);
  const [narrativeInitialData, setNarrativeInitialData] = useState<{b64: string, mime: string, name: string} | null>(null);

  useEffect(() => {
    setBookmarks(getBookmarks());
    // Hydrate workspace from bookmarks or just empty session
    const docBookmarks = getBookmarks().filter(b => b.type === 'document_analysis') as any[];
    if (docBookmarks.length > 0) {
      setDocumentWorkspaceFiles(docBookmarks.map(b => b.result));
    }
  }, []);

  const executeSearch = useCallback(async (params: SearchParams) => {
    const finalParams: SearchParams = { ...params, query: params.query.trim() };

    if (!finalParams.query) {
      setError('Neural scan requires query input.');
      return;
    }
    if (finalParams.query.length > MAX_QUERY_LENGTH) {
      setError(`Payload exceeds char limit.`);
      return;
    }

    const cachedResult = getCachedResult(finalParams);
    if (cachedResult) {
      setOutput({
        ...cachedResult,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false,
      });
      setCurrentSearchParamsForResults(finalParams);
      setError(null);
      return;
    }

    setIsLoading(true);
    setError(null);
    setOutput({
      summary: '',
      sources: [],
      followUpQuestions: [],
      relatedQueries: [],
      timelineEvents: [],
      identifiedJudges: [],
      isSummaryStreaming: true,
      isFollowUpQuestionsLoading: false,
      isRelatedQueriesLoading: false,
      isTimelineLoading: false,
      isIdentifiedJudgesLoading: false,
    });
    setCurrentSearchParamsForResults(finalParams);

    try {
      const result = await searchWebWithGemini(finalParams, (partial) => {
        setOutput(prev => ({ ...prev!, ...partial }));
      });
      setOutput(prev => ({
          ...prev!,
          ...result,
          isSummaryStreaming: false,
      }));
      setCachedResult(finalParams, result);
      addToHistory(finalParams);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Dossier synthesis failure.');
      setOutput(null);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleSearch = useCallback(() => executeSearch(searchParams), [searchParams, executeSearch]);

  const handleSaveResult = (params: SearchParams, result: SearchResult) => {
    const key = generateSearchKey(params);
    saveBookmark({ key, type: 'search', params, result, savedAt: Date.now() });
    setBookmarks(getBookmarks());
  };

  const handleRemoveSave = (params: SearchParams) => {
    removeBookmark(generateSearchKey(params));
    setBookmarks(getBookmarks());
  };

  const handleViewBookmark = (bookmark: Bookmark) => {
    if (bookmark.type === 'search') {
        setSearchParams(bookmark.params);
        setOutput({ ...bookmark.result, isSummaryStreaming: false });
        setCurrentSearchParamsForResults(bookmark.params);
        setActiveTab('copilot');
    } else if (bookmark.type === 'document_analysis') {
        setActiveWorkspaceFileId(bookmark.result.id || null);
        setActiveTab('audit');
    } else if (bookmark.type === 'cross_reference') {
        setCrossRefResult(bookmark.result);
        setShowCrossRefModal(true);
    }
  };

  const handleWorkspaceUpload = async (b64: string, mime: string, name: string) => {
    // Initial placeholder
    const tempId = crypto.randomUUID();
    const placeholder: DocumentAnalysisResult = {
      id: tempId,
      fileName: name,
      uploadDate: Date.now(),
      status: 'analyzing',
      strategicSummary: '',
      keyArguments: [],
      identifiedEntities: [],
      actionableInsights: []
    };
    setDocumentWorkspaceFiles(prev => [placeholder, ...prev]);
    setActiveWorkspaceFileId(tempId);

    try {
      const result = await analyzeDocument(b64, mime, name);
      setDocumentWorkspaceFiles(prev => prev.map(f => f.id === tempId ? { ...result, id: tempId } : f));
      // Auto-save to vault
      saveBookmark({
        key: generateDocKey(name),
        type: 'document_analysis',
        result: { ...result, id: tempId },
        savedAt: Date.now()
      });
      setBookmarks(getBookmarks());
    } catch (e) {
      setDocumentWorkspaceFiles(prev => prev.map(f => f.id === tempId ? { ...f, status: 'error', strategicSummary: 'Audit failure.' } : f));
    }
  };

  const handleRemoveWorkspaceFile = (id: string) => {
    const file = documentWorkspaceFiles.find(f => f.id === id);
    if (file) {
      removeBookmark(generateDocKey(file.fileName));
      setBookmarks(getBookmarks());
    }
    setDocumentWorkspaceFiles(prev => prev.filter(f => f.id !== id));
    if (activeWorkspaceFileId === id) setActiveWorkspaceFileId(null);
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-12 flex flex-col bg-[#020617]">
      <Banner />

      <div className="flex-grow flex flex-col lg:flex-row max-w-[1800px] mx-auto w-full px-4 lg:px-12 gap-8 lg:gap-12 mt-6 lg:mt-12">

        {/* Navigation Sidebar (Desktop Only) */}
        <aside className="hidden lg:flex lg:w-72 flex-col gap-10">
          <Header 
            onAnalyzeDocumentClick={() => setActiveTab('audit')} 
            onCrossReferenceClick={() => setShowCrossRefModal(true)} 
            onNarrativeMapperClick={() => setShowNarrativeMapper(true)}
          />
          <Bookmarks 
            bookmarks={bookmarks}
            onView={handleViewBookmark}
            onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
          />
        </aside>

        {/* Main Content Area */}
        <div className="flex-grow flex flex-col gap-8">
          {activeTab === 'copilot' && (
            <main className="flex flex-col gap-8 lg:gap-12 animate-in fade-in duration-500">
              <div className="tech-plate overflow-hidden">
                <SearchForm
                  params={searchParams}
                  setParams={setSearchParams}
                  onSearch={handleSearch}
                  isLoading={isLoading}
                  onClear={() => { setOutput(null); setSearchParams({...searchParams, query: ''}); }}
                  onSelectHistory={(p) => { setSearchParams(p); executeSearch(p); }}
                  onSave={() => currentSearchParamsForResults && output && handleSaveResult(currentSearchParamsForResults, output)}
                  onImportPDF={() => setActiveTab('audit')}
                  canSave={!!output && !!currentSearchParamsForResults}
                />
                <div className="px-6 lg:px-10 pb-6 lg:pb-10 pt-4 lg:pt-6">
                  <Examples onSelectExample={(ex) => setSearchParams({...searchParams, ...ex})} />
                </div>
              </div>

              {error && (
                <div className="bg-red-950/20 border border-red-900/40 p-4 lg:p-6 etched-label text-red-500 flex items-center gap-4 animate-pulse">
                  <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                  SYSTEM_FAULT: {error}
                </div>
              )}

              <ResultsDisplay
                output={output}
                searchParams={currentSearchParamsForResults}
                isLoading={isLoading}
                onQuestionClick={(q) => { setSearchParams({...searchParams, query: q}); executeSearch({...searchParams, query: q}); }}
                onAnalysisClick={() => {}}
                onSave={handleSaveResult}
                onRemoveSave={handleRemoveSave}
                isSaved={currentSearchParamsForResults ? isSearchBookmarked(currentSearchParamsForResults) : false}
                onJudgeClick={(name) => { setSelectedJudgeName(name); setShowJudgeModal(true); }}
              />
            </main>
          )}

          {activeTab === 'audit' && (
            <DocumentWorkspace 
              files={documentWorkspaceFiles}
              activeFileId={activeWorkspaceFileId}
              onSelectFile={setActiveWorkspaceFileId}
              onUpload={handleWorkspaceUpload}
              onRemove={handleRemoveWorkspaceFile}
              onMapNarrative={(file) => {
                // If the user wants narrative mapper, we'd need the base64 again, 
                // but for this UI, we just open a mapper or use the file object.
                setShowNarrativeMapper(true);
              }}
            />
          )}

          {activeTab === 'vault' && (
            <div className="lg:hidden animate-in slide-in-from-right duration-300">
               <Bookmarks 
                bookmarks={bookmarks}
                onView={handleViewBookmark}
                onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
              />
            </div>
          )}
        </div>
      </div>

      <footer className="mt-20 mb-8 lg:mb-0 text-center etched-label opacity-20 tracking-[0.4em] lg:tracking-[0.6em] px-4 text-[8px] lg:text-[10px]">
        PRECISION_LEGAL_ANALYSIS_NODE // GEMINI_v3_CORE
      </footer>

      {/* Mobile Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 lg:hidden bg-[#0a0a0a]/90 backdrop-blur-2xl border-t border-white/5 z-[60] pb-safe">
        <div className="flex justify-around items-center h-20 px-4">
          <button 
            onClick={() => setActiveTab('copilot')}
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'copilot' ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <HistoryIcon className="w-6 h-6" />
            <span className="text-[9px] font-black uppercase tracking-widest">Counsel</span>
          </button>

          <button 
            onClick={() => setActiveTab('audit')}
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'audit' ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <BrainCircuitIcon className="w-6 h-6" />
            <span className="text-[9px] font-black uppercase tracking-widest">Workspace</span>
          </button>

          <button 
            onClick={() => setActiveTab('vault')}
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'vault' ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <BookmarkIcon className="w-6 h-6" />
            <span className="text-[9px] font-black uppercase tracking-widest">Vault</span>
          </button>
        </div>
      </nav>

      {showJudgeModal && selectedJudgeName && (
        <JudgeDetailModal judgeName={selectedJudgeName} onClose={() => setShowJudgeModal(false)} />
      )}

      {showCrossRefModal && (
        <CrossReferenceModal
          onClose={() => setShowCrossRefModal(false)}
          onAnalyze={async (a, am, an, b, bm, bn) => {
            setIsCrossRefLoading(true);
            try { setCrossRefResult(await crossReferenceDocuments(a, am, an, b, bm, bn)); }
            catch(e) { console.error(e); }
            finally { setIsCrossRefLoading(false); }
          }}
          result={crossRefResult}
          isLoading={isCrossRefLoading}
          error={null}
          onSave={(res) => {
            saveBookmark({
              key: generateCrossRefKey(res.fileAName, res.fileBName),
              type: 'cross_reference',
              result: res,
              savedAt: Date.now()
            });
            setBookmarks(getBookmarks());
          }}
          onRemoveSave={(r) => {
            removeBookmark(generateCrossRefKey(r.fileAName, r.fileBName));
            setBookmarks(getBookmarks());
          }}
          isSaved={crossRefResult ? isCrossRefBookmarked(crossRefResult.fileAName, crossRefResult.fileBName) : false}
        />
      )}
      {showNarrativeMapper && (
        <NarrativeMapper 
          onClose={() => { setShowNarrativeMapper(false); setNarrativeInitialData(null); }} 
          initialData={narrativeInitialData}
          onGenerate={async (b, m, n) => await generateNarrativeMap(b, m, n)}
        />
      )}
    </div>
  );
}

import React, { useState, useRef, useCallback } from 'react';
import { DocumentAnalysisResult, DocumentAnnotation } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import DocumentIcon from './icons/DocumentIcon';
import CloseIcon from './icons/CloseIcon';
import TrashIcon from './icons/TrashIcon';
import AlertIcon from './icons/AlertIcon';
import SparklesIcon from './icons/SparklesIcon';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

interface DocumentWorkspaceProps {
  files: DocumentAnalysisResult[];
  activeFileId: string | null;
  onSelectFile: (id: string) => void;
  onUpload: (b64: string, mime: string, name: string) => void;
  onRemove: (id: string) => void;
  onMapNarrative: (file: DocumentAnalysisResult) => void;
}

const AnnotationCard: React.FC<{ annotation: DocumentAnnotation }> = ({ annotation }) => {
  const priorityColors = {
    high: 'border-red-500 bg-red-500/5 text-red-400',
    medium: 'border-orange-500 bg-orange-500/5 text-orange-400',
    low: 'border-blue-500 bg-blue-500/5 text-blue-400'
  };

  const typeIcons = {
    risk: 'fas fa-exclamation-triangle',
    opportunity: 'fas fa-lightbulb',
    discrepancy: 'fas fa-not-equal',
    procedural: 'fas fa-gavel'
  };

  return (
    <div className={`p-4 border-l-2 mb-4 rounded-r-lg transition-all hover:shadow-lg ${priorityColors[annotation.priority]}`}>
      <div className="flex items-center justify-between mb-2">
        <span className="text-[8px] font-black uppercase tracking-[0.2em] flex items-center gap-2">
           <i className={(typeIcons as any)[annotation.type] || 'fas fa-info-circle'}></i>
           {annotation.type} Protocol
        </span>
        <span className="text-[8px] font-bold opacity-60">Annotation #{annotation.id.substring(0, 4)}</span>
      </div>
      {annotation.quote && (
        <div className="text-[10px] italic border-l border-current/20 pl-2 mb-2 opacity-80">
          "{annotation.quote}"
        </div>
      )}
      <p className="text-xs font-medium leading-relaxed">
        {annotation.text}
      </p>
    </div>
  );
};

export default function DocumentWorkspace({ 
  files, 
  activeFileId, 
  onSelectFile, 
  onUpload, 
  onRemove,
  onMapNarrative
}: DocumentWorkspaceProps): React.ReactNode {
  const [dragActive, setDragActive] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const activeFile = files.find(f => f.id === activeFileId);

  const handleFile = useCallback((file: File) => {
    if (file.type !== 'application/pdf') return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const b64 = (e.target?.result as string).split(',')[1];
      onUpload(b64, file.type, file.name);
    };
    reader.readAsDataURL(file);
  }, [onUpload]);

  return (
    <div className="flex flex-col lg:flex-row h-full min-h-[70vh] gap-8 animate-in fade-in duration-500">

      {/* File List Sidebar */}
      <div className="w-full lg:w-80 flex flex-col gap-6">
        <div className="law-card p-6 flex flex-col gap-6">
           <div className="flex justify-between items-center px-1">
             <h3 className="etched-label">Case Dossiers</h3>
             <div className="flex items-center gap-2">
               <span className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></span>
               <span className="text-[9px] font-bold text-slate-500">Encrypted</span>
             </div>
           </div>

           <div className="space-y-2">
              <button 
                onClick={() => inputRef.current?.click()}
                className="w-full p-4 bg-slate-950 border border-slate-800 rounded flex flex-col items-center justify-center gap-2 group hover:border-blue-500/40 transition-all"
              >
                <i className="fas fa-plus text-slate-700 group-hover:text-blue-500"></i>
                <span className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Inject PDF</span>
              </button>
              <input ref={inputRef} type="file" accept="application/pdf" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} />
           </div>

           <div className="flex-grow space-y-3 max-h-[400px] overflow-y-auto no-scrollbar">
              {files.length === 0 && (
                <div className="p-8 text-center opacity-20 italic text-[10px] text-slate-500">
                  No dossiers loaded in current session.
                </div>
              )}
              {files.map(file => (
                <div 
                  key={file.id} 
                  onClick={() => onSelectFile(file.id!)}
                  className={`p-4 border rounded cursor-pointer transition-all relative group ${
                    activeFileId === file.id ? 'bg-slate-800 border-blue-500 shadow-lg' : 'bg-slate-900 border-white/5 hover:border-white/10'
                  }`}
                >
                   <div className="flex items-start justify-between mb-1">
                      <span className="text-[10px] font-bold text-slate-200 truncate pr-4">{file.fileName}</span>
                      <button onClick={(e) => { e.stopPropagation(); onRemove(file.id!); }} className="text-slate-700 hover:text-red-500 transition-colors">
                        <TrashIcon className="w-3 h-3" />
                      </button>
                   </div>
                   <div className="flex items-center gap-2 mt-2">
                      <div className={`w-1.5 h-1.5 rounded-full ${
                        file.status === 'analyzing' ? 'bg-amber-500 animate-pulse' : 
                        file.status === 'error' ? 'bg-red-500' : 'bg-emerald-500'
                      }`}></div>
                      <span className="text-[8px] font-black uppercase tracking-widest text-slate-500">
                        {file.status === 'analyzing' ? 'Neural Synthesis...' : file.status.toUpperCase()}
                      </span>
                   </div>
                </div>
              ))}
           </div>
        </div>

        <div className="law-card p-6 bg-blue-500/[0.03] border-blue-500/10">
           <h4 className="etched-label text-blue-500/60 mb-3">Privacy Guarantee</h4>
           <p className="text-[10px] text-slate-500 leading-relaxed italic">
             This workspace operates in an isolated neural context. All uploaded discovery material is encrypted and used only for strategy synthesis.
           </p>
        </div>
      </div>

      {/* Main Analysis/Review Area */}
      <div className="flex-grow relative min-h-[600px]">
        {!activeFile ? (
          <div 
            onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
            onDragLeave={() => setDragActive(false)}
            onDrop={(e) => { e.preventDefault(); setDragActive(false); e.dataTransfer.files && handleFile(e.dataTransfer.files[0]); }}
            className={`absolute inset-0 law-card flex flex-col items-center justify-center gap-6 border-2 border-dashed transition-all ${
              dragActive ? 'border-blue-500 bg-blue-500/5' : 'border-white/5 bg-slate-950/20'
            }`}
          >
            <div className="p-8 bg-slate-900 rounded-full border border-white/5 text-slate-700">
              <DocumentIcon className="w-12 h-12" />
            </div>
            <div className="text-center space-y-2">
               <h3 className="serif-heading text-2xl text-slate-300">Discovery Workspace</h3>
               <p className="text-slate-500 text-xs font-medium">Select a dossier or drop a new PDF to begin strategic audit.</p>
            </div>
          </div>
        ) : activeFile.status === 'analyzing' ? (
          <div className="absolute inset-0 law-card flex flex-col items-center justify-center gap-8 p-20">
             <div className="relative">
               <div className="w-24 h-24 border-2 border-blue-500/10 border-t-blue-500 rounded-full animate-spin"></div>
               <div className="absolute inset-4 border-2 border-slate-800 border-b-amber-500/40 rounded-full animate-spin-slow"></div>
               <SparklesIcon className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-blue-500 w-6 h-6 animate-pulse" />
             </div>
             <div className="text-center space-y-4">
               <span className="etched-label animate-pulse">Neural Harvesting in Progress...</span>
               <div className="flex flex-col items-center gap-1 opacity-40">
                  <span className="text-[9px] font-mono uppercase text-slate-500">Mapping Entity Clusters</span>
                  <span className="text-[9px] font-mono uppercase text-slate-500">Correlating Colorado Statutes</span>
               </div>
             </div>
          </div>
        ) : (
          <div className="flex flex-col lg:flex-row gap-8 h-full">

             {/* Document Synthesis Brief */}
             <div className="flex-grow flex flex-col gap-8 overflow-y-auto no-scrollbar pb-20">
                <div className="law-card p-10 lg:p-12 relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/[0.02] blur-3xl rounded-full"></div>

                   <div className="flex flex-col md:flex-row justify-between items-start border-b border-white/5 pb-8 mb-8 gap-4">
                      <div>
                        <div className="flex items-center gap-2 mb-2">
                          <span className="etched-label text-[10px]">Strategic Synthesis Report</span>
                        </div>
                        <h2 className="text-3xl font-bold text-white serif-heading tracking-tight">Audit: {activeFile.fileName}</h2>
                      </div>
                      <button 
                        onClick={() => onMapNarrative(activeFile)}
                        className="px-6 py-2 bg-slate-900 border border-white/10 hover:border-blue-500/40 text-xs font-black uppercase text-slate-400 hover:text-white transition-all rounded-lg"
                      >
                         Map Narrative Matrix
                      </button>
                   </div>

                   <div className="prose prose-invert prose-lg max-w-none text-slate-300 mb-12">
                      <ReactMarkdown remarkPlugins={[remarkGfm]}>{activeFile.strategicSummary}</ReactMarkdown>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-4">
                        <h4 className="etched-label opacity-40">Tactical Arguments</h4>
                        <ul className="space-y-3">
                           {activeFile.keyArguments.map((arg, i) => (
                             <li key={i} className="flex gap-4 p-4 bg-slate-900/40 border border-white/5 rounded-lg text-sm text-slate-300 font-medium leading-relaxed">
                               <span className="text-blue-500 font-mono text-[10px]">0{i+1}</span>
                               {arg}
                             </li>
                           ))}
                        </ul>
                      </div>
                      <div className="space-y-4">
                        <h4 className="etched-label opacity-40">Entities Detected</h4>
                        <div className="grid grid-cols-2 gap-3">
                           {activeFile.identifiedEntities.map((ent, i) => (
                             <div key={i} className="p-3 bg-slate-900/40 border border-white/5 rounded-lg text-xs">
                                <span className="text-[8px] font-black uppercase tracking-widest text-slate-500 block mb-1">{ent.type}</span>
                                <span className="text-slate-300 font-bold">{ent.value}</span>
                             </div>
                           ))}
                        </div>
                      </div>
                   </div>
                </div>

                <div className="law-card p-10 border-blue-500/10 bg-blue-500/[0.01]">
                   <h4 className="etched-label mb-8">Strategic Outlook</h4>
                   <div className="space-y-4">
                      {activeFile.actionableInsights.map((insight, i) => (
                        <div key={i} className="flex items-center gap-6 group">
                           <div className="w-10 h-10 rounded bg-slate-900 border border-white/5 flex items-center justify-center shrink-0 group-hover:border-blue-500/30 transition-all">
                              <i className="fas fa-arrow-right text-[10px] text-slate-600 group-hover:text-blue-500"></i>
                           </div>
