import React, { useState, useCallback, useRef } from 'react';
import { CrossReferenceResult } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import DocumentIcon from './icons/DocumentIcon';
import CloseIcon from './icons/CloseIcon';
import ScaleIcon from './icons/ScaleIcon';
import AlertIcon from './icons/AlertIcon';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';

interface CrossReferenceModalProps {
    onClose: () => void;
    onReset: () => void;
    onAnalyze: (
        fileABase64: string, fileAMime: string, fileAName: string,
        fileBBase64: string, fileBMime: string, fileBName: string
    ) => Promise<void>;
    result: CrossReferenceResult | null;
    isLoading: boolean;
    error: string | null;
    onSave: (result: CrossReferenceResult) => void;
    onRemoveSave: (result: CrossReferenceResult) => void;
    isSaved: boolean;
}

const MAX_FILE_SIZE_MB = 10;

const SeverityBadge: React.FC<{ severity: 'high' | 'medium' | 'low' }> = ({ severity }) => {
    switch (severity) {
        case 'high':
            return <span className="px-2 py-0.5 rounded text-[8px] font-black bg-red-950 text-red-500 border border-red-500/30 uppercase tracking-widest">High Risk</span>;
        case 'medium':
            return <span className="px-2 py-0.5 rounded text-[8px] font-black bg-orange-950 text-orange-500 border border-orange-500/30 uppercase tracking-widest">Conflict</span>;
        case 'low':
            return <span className="px-2 py-0.5 rounded text-[8px] font-black bg-blue-950 text-blue-500 border border-blue-500/30 uppercase tracking-widest">Minor</span>;
    }
};

const FileUploader: React.FC<{
    label: string;
    file: File | null;
    onSetFile: (f: File | null) => void;
}> = ({ label, file, onSetFile }) => {
    const inputRef = useRef<HTMLInputElement>(null);
    const [dragActive, setDragActive] = useState(false);
    return (
        <div 
            className={`border border-dashed p-10 text-center cursor-pointer transition-all ${dragActive ? 'border-[#b5892f] bg-[#b5892f]/5' : 'border-[#6e501a]/30 bg-[#050505] hover:border-[#b5892f]/40'}`}
            onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
            onDragLeave={() => setDragActive(false)}
            onDrop={(e) => { e.preventDefault(); setDragActive(false); onSetFile(e.dataTransfer.files[0]); }}
            onClick={() => inputRef.current?.click()}
        >
            <input ref={inputRef} type="file" accept="application/pdf" className="hidden" onChange={(e) => e.target.files && onSetFile(e.target.files[0])} />
            {file ? (
                <div className="flex flex-col items-center">
                    <DocumentIcon className="w-10 h-10 text-[#b5892f] mb-4" />
                    <p className="text-xs font-black text-white uppercase tracking-widest truncate max-w-[200px]">{file.name}</p>
                </div>
            ) : (
                <div className="flex flex-col items-center">
                    <DocumentIcon className="w-10 h-10 text-[#6e501a] opacity-30 mb-4" />
                    <p className="text-[10px] font-black text-[#6e501a] uppercase tracking-widest">{label}</p>
                </div>
            )}
        </div>
    );
};

export default function CrossReferenceModal({ onClose, onReset, onAnalyze, result, isLoading, error, onSave, onRemoveSave, isSaved }: CrossReferenceModalProps): React.ReactNode {
    const [fileA, setFileA] = useState<File | null>(null);
    const [fileB, setFileB] = useState<File | null>(null);

    const handleReset = useCallback(() => {
        setFileA(null);
        setFileB(null);
        onReset();
    }, [onReset]);

    const handleAnalyzeClick = async () => {
        if (!fileA || !fileB) return;
        const toBase64 = (f: File) => new Promise<string>((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve((reader.result as string).split(',')[1]);
            reader.readAsDataURL(f);
        });
        const [b64A, b64B] = await Promise.all([toBase64(fileA), toBase64(fileB)]);
        await onAnalyze(b64A, fileA.type, fileA.name, b64B, fileB.type, fileB.name);
    };

    return (
        <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4" onClick={(e) => e.target === e.currentTarget && onClose()}>
            <div className="bg-[#121212] border border-[#6e501a] shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-y-auto custom-scrollbar relative">
                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-[#6e501a] via-[#b5892f] to-[#6e501a]"></div>

                <div className="flex justify-between items-center p-6 border-b border-[#6e501a]/20">
                    <div className="flex items-center gap-4">
                        <ScaleIcon className="w-6 h-6 text-[#b5892f]" />
                        <h2 className="text-xl font-black text-[#efefef] uppercase tracking-[0.2em] italic">Cross-Examination Engine</h2>
                    </div>
                    <div className="flex items-center gap-4">
                        {(fileA || fileB || result) && (
                            <button 
                                onClick={handleReset}
                                className="px-3 py-1 text-[10px] font-black text-red-500/60 hover:text-red-500 hover:bg-red-500/5 border border-transparent hover:border-red-500/20 uppercase tracking-widest transition-all"
                            >
                                [Clear All]
                            </button>
                        )}
                        {result && (
                             <button onClick={() => isSaved ? onRemoveSave(result) : onSave(result)} className="text-[#b5892f] hover:text-[#e2c07d]">
                                {isSaved ? <BookmarkFilledIcon className="w-6 h-6" /> : <BookmarkIcon className="w-6 h-6" />}
                            </button>
                        )}
                        <button onClick={onClose} className="text-[#6e501a] hover:text-[#efefef]"><CloseIcon className="w-6 h-6" /></button>
                    </div>
                </div>

                <div className="p-10">
                    {!result && !isLoading ? (
                        <div className="space-y-12">
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                                <FileUploader label="Primary Dossier" file={fileA} onSetFile={setFileA} />
                                <FileUploader label="Corroborating Evidence" file={fileB} onSetFile={setFileB} />
                            </div>
                            <button onClick={handleAnalyzeClick} disabled={!fileA || !fileB} className="w-full py-6 bg-[#b5892f] text-[#050505] font-black uppercase italic tracking-tighter text-2xl hover:bg-[#e2c07d] transition-all disabled:opacity-20 shadow-xl">
                                INITIATE CROSS-REFERENCE
                            </button>
                        </div>
                    ) : isLoading ? (
                        <div className="flex flex-col items-center justify-center py-20">
                            <SpinnerIcon className="w-14 h-14 text-[#b5892f] mb-8" />
                            <h3 className="text-xl font-black text-[#efefef] uppercase tracking-[0.3em] animate-pulse italic">Auditing Credibility...</h3>
                            <p className="text-[#6e501a] font-mono text-[9px] mt-4 uppercase tracking-[0.4em]">Matching semantic discrepancies in vector space</p>
                        </div>
                    ) : result ? (
                        <div className="space-y-12 animate-[fadeIn_0.5s_ease-out]">
                            <div className="flex flex-col md:flex-row items-stretch gap-8 bg-[#050505] p-8 border border-[#6e501a]/30 shadow-inner">
                                <div className="flex flex-col items-center justify-center border-r border-[#6e501a]/20 pr-8 md:w-48">
                                    <div className="text-4xl font-black text-[#b5892f] italic tracking-tighter">{result.overallCredibilityScore}%</div>
                                    <div className="text-[9px] font-black text-[#6e501a] uppercase tracking-widest mt-2">Dossier Integrity</div>
                                </div>
                                <div className="flex-grow pl-0 md:pl-4">
                                    <h4 className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.3em] mb-4">Strategic Discrepancy Map</h4>
                                    <p className="text-base text-white font-light leading-relaxed">{result.summaryOfDiscrepancies}</p>
                                </div>
                            </div>

                            <div className="space-y-6">
                                <h3 className="text-[10px] font-black text-[#efefef] uppercase tracking-[0.4em] mb-6 flex items-center gap-4">
                                    Detected Anomalies ({result.contradictions.length})
                                    <div className="h-px flex-grow bg-[#6e501a]/20"></div>
                                </h3>
                                <div className="grid grid-cols-1 gap-6">
                                    {result.contradictions.map((c, i) => (
                                        <div key={i} className="bg-[#050505] border border-[#6e501a]/40 p-6 group hover:border-[#b5892f]/40 transition-all">
                                            <div className="flex justify-between items-start mb-6">
                                                <h4 className="text-lg font-black text-[#e2c07d] uppercase tracking-wider italic">{c.topic}</h4>
                                                <SeverityBadge severity={c.severity as any} />
                                            </div>
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                                                <div className="p-4 bg-[#121212] border-l-2 border-red-900">
                                                    <span className="text-[9px] font-black text-[#6e501a] uppercase block mb-2">Claim Node A</span>
                                                    <p className="text-sm text-slate-300 italic">"{c.sourceAClaim}"</p>
                                                </div>
                                                <div className="p-4 bg-[#121212] border-l-2 border-blue-900">
                                                    <span className="text-[9px] font-black text-[#6e501a] uppercase block mb-2">Claim Node B</span>
                                                    <p className="text-sm text-slate-300 italic">"{c.sourceBClaim}"</p>
                                                </div>
                                            </div>
                                            <p className="text-xs text-white bg-[#b5892f]/5 p-4 border border-[#b5892f]/10 leading-relaxed font-bold">
                                                <span className="text-[#6e501a] mr-2 font-mono uppercase text-[9px]">Tactical Analysis:</span>
                                                {c.analysis}
                                            </p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : null}
                </div>
            </div>
            <style>{`@keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }`}</style>
        </div>
    );
}

import React, { useState, useCallback, useEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, type Bookmark, CaseType, Jurisdiction, type SearchResult, type DocumentAnalysisResult, type CrossReferenceResult } from './types';
import { searchWebWithGemini, analyzeDocument, crossReferenceDocuments, generateNarrativeMap } from './services/geminiService';
import { getCachedResult, setCachedResult } from './services/cacheService';
import { addToHistory } from './services/historyService';
import { getBookmarks, saveBookmark, removeBookmark, isSearchBookmarked, isDocBookmarked, isCrossRefBookmarked, generateSearchKey, generateDocKey, generateCrossRefKey } from './services/bookmarkService';
import { MAX_QUERY_LENGTH } from './constants';
import Header from './components/Header';
import Banner from './components/Banner';
import SearchForm from './components/SearchForm';
import ResultsDisplay from './components/ResultsDisplay';
import Examples from './components/Examples';
import Bookmarks from './components/Bookmarks';
import JudgeDetailModal from './components/JudgeDetailModal';
import CrossReferenceModal from './components/CrossReferenceModal';
import NarrativeMapper from './components/NarrativeMapper';
import DocumentWorkspace from './components/DocumentWorkspace';
import BrainCircuitIcon from './components/icons/BrainCircuitIcon';
import BookmarkIcon from './components/icons/BookmarkIcon';
import HistoryIcon from './components/icons/HistoryIcon';

type AppTab = 'copilot' | 'audit' | 'vault';

export default function App(): React.ReactNode {
  const [activeTab, setActiveTab] = useState<AppTab>('copilot');
  const [searchParams, setSearchParams] = useState<SearchParams>({
    query: '',
    searchType: SearchType.SEARCH,
    listCount: undefined,
    dateRange: DateRange.ANY,
    siteRestrict: '',
    fileType: '',
    partyName: '',
    caseNumber: '',
    caseStatus: CaseStatus.ALL,
    caseType: CaseType.ALL,
    jurisdiction: Jurisdiction.ALL,
  });
  const [currentSearchParamsForResults, setCurrentSearchParamsForResults] = useState<SearchParams | null>(null);
  const [output, setOutput] = useState<SearchResult | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  const [showJudgeModal, setShowJudgeModal] = useState(false);
  const [selectedJudgeName, setSelectedJudgeName] = useState<string | null>(null);

  const [documentWorkspaceFiles, setDocumentWorkspaceFiles] = useState<DocumentAnalysisResult[]>([]);
  const [activeWorkspaceFileId, setActiveWorkspaceFileId] = useState<string | null>(null);

  const [showCrossRefModal, setShowCrossRefModal] = useState(false);
  const [crossRefResult, setCrossRefResult] = useState<CrossReferenceResult | null>(null);
  const [isCrossRefLoading, setIsCrossRefLoading] = useState(false);

  const [showNarrativeMapper, setShowNarrativeMapper] = useState(false);
  const [narrativeInitialData, setNarrativeInitialData] = useState<{b64: string, mime: string, name: string} | null>(null);

  useEffect(() => {
    setBookmarks(getBookmarks());
    // Hydrate workspace from bookmarks or just empty session
    const docBookmarks = getBookmarks().filter(b => b.type === 'document_analysis') as any[];
    if (docBookmarks.length > 0) {
      setDocumentWorkspaceFiles(docBookmarks.map(b => b.result));
    }
  }, []);

  const executeSearch = useCallback(async (params: SearchParams) => {
    const finalParams: SearchParams = { ...params, query: params.query.trim() };

    if (!finalParams.query) {
      setError('Neural scan requires query input.');
      return;
    }
    if (finalParams.query.length > MAX_QUERY_LENGTH) {
      setError(`Payload exceeds char limit.`);
      return;
    }

    const cachedResult = getCachedResult(finalParams);
    if (cachedResult) {
      setOutput({
        ...cachedResult,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false,
      });
      setCurrentSearchParamsForResults(finalParams);
      setError(null);
      return;
    }

    setIsLoading(true);
    setError(null);
    setOutput({
      summary: '',
      sources: [],
      followUpQuestions: [],
      relatedQueries: [],
      timelineEvents: [],
      identifiedJudges: [],
      isSummaryStreaming: true,
      isFollowUpQuestionsLoading: false,
      isRelatedQueriesLoading: false,
      isTimelineLoading: false,
      isIdentifiedJudgesLoading: false,
    });
    setCurrentSearchParamsForResults(finalParams);

    try {
      const result = await searchWebWithGemini(finalParams, (partial) => {
        setOutput(prev => ({ ...prev!, ...partial }));
      });
      setOutput(prev => ({
          ...prev!,
          ...result,
          isSummaryStreaming: false,
      }));
      setCachedResult(finalParams, result);
      addToHistory(finalParams);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Dossier synthesis failure.');
      setOutput(null);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleSearch = useCallback(() => executeSearch(searchParams), [searchParams, executeSearch]);

  const handleSaveResult = (params: SearchParams, result: SearchResult) => {
    const key = generateSearchKey(params);
    saveBookmark({ key, type: 'search', params, result, savedAt: Date.now() });
    setBookmarks(getBookmarks());
  };

  const handleRemoveSave = (params: SearchParams) => {
    removeBookmark(generateSearchKey(params));
    setBookmarks(getBookmarks());
  };

  const handleViewBookmark = (bookmark: Bookmark) => {
    if (bookmark.type === 'search') {
        setSearchParams(bookmark.params);
        setOutput({ ...bookmark.result, isSummaryStreaming: false });
        setCurrentSearchParamsForResults(bookmark.params);
        setActiveTab('copilot');
    } else if (bookmark.type === 'document_analysis') {
        setActiveWorkspaceFileId(bookmark.result.id || null);
        setActiveTab('audit');
    } else if (bookmark.type === 'cross_reference') {
        setCrossRefResult(bookmark.result);
        setShowCrossRefModal(true);
    }
  };

  const handleWorkspaceUpload = async (b64: string, mime: string, name: string) => {
    // Initial placeholder
    const tempId = crypto.randomUUID();
    const placeholder: DocumentAnalysisResult = {
      id: tempId,
      fileName: name,
      uploadDate: Date.now(),
      status: 'analyzing',
      strategicSummary: '',
      keyArguments: [],
      identifiedEntities: [],
      actionableInsights: []
    };
    setDocumentWorkspaceFiles(prev => [placeholder, ...prev]);
    setActiveWorkspaceFileId(tempId);

    try {
      const result = await analyzeDocument(b64, mime, name);
      setDocumentWorkspaceFiles(prev => prev.map(f => f.id === tempId ? { ...result, id: tempId } : f));
      // Auto-save to vault
      saveBookmark({
        key: generateDocKey(name),
        type: 'document_analysis',
        result: { ...result, id: tempId },
        savedAt: Date.now()
      });
      setBookmarks(getBookmarks());
    } catch (e) {
      setDocumentWorkspaceFiles(prev => prev.map(f => f.id === tempId ? { ...f, status: 'error', strategicSummary: 'Audit failure.' } : f));
    }
  };

  const handleRemoveWorkspaceFile = (id: string) => {
    const file = documentWorkspaceFiles.find(f => f.id === id);
    if (file) {
      removeBookmark(generateDocKey(file.fileName));
      setBookmarks(getBookmarks());
    }
    setDocumentWorkspaceFiles(prev => prev.filter(f => f.id !== id));
    if (activeWorkspaceFileId === id) setActiveWorkspaceFileId(null);
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-12 flex flex-col bg-[#020617]">
      <Banner />

      <div className="flex-grow flex flex-col lg:flex-row max-w-[1800px] mx-auto w-full px-4 lg:px-12 gap-8 lg:gap-12 mt-6 lg:mt-12">

        {/* Navigation Sidebar (Desktop Only) */}
        <aside className="hidden lg:flex lg:w-72 flex-col gap-10">
          <Header 
            onAnalyzeDocumentClick={() => setActiveTab('audit')} 
            onCrossReferenceClick={() => setShowCrossRefModal(true)} 
            onNarrativeMapperClick={() => setShowNarrativeMapper(true)}
          />
          <Bookmarks 
            bookmarks={bookmarks}
            onView={handleViewBookmark}
            onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
          />
        </aside>

        {/* Main Content Area */}
        <div className="flex-grow flex flex-col gap-8">
          {activeTab === 'copilot' && (
            <main className="flex flex-col gap-8 lg:gap-12 animate-in fade-in duration-500">
              <div className="tech-plate overflow-hidden">
                <SearchForm
                  params={searchParams}
                  setParams={setSearchParams}
                  onSearch={handleSearch}
                  isLoading={isLoading}
                  onClear={() => { setOutput(null); setSearchParams({...searchParams, query: ''}); }}
                  onSelectHistory={(p) => { setSearchParams(p); executeSearch(p); }}
                  onSave={() => currentSearchParamsForResults && output && handleSaveResult(currentSearchParamsForResults, output)}
                  onImportPDF={() => setActiveTab('audit')}
                  canSave={!!output && !!currentSearchParamsForResults}
                />
                <div className="px-6 lg:px-10 pb-6 lg:pb-10 pt-4 lg:pt-6">
                  <Examples onSelectExample={(ex) => setSearchParams({...searchParams, ...ex})} />
                </div>
              </div>

              {error && (
                <div className="bg-red-950/20 border border-red-900/40 p-4 lg:p-6 etched-label text-red-500 flex items-center gap-4 animate-pulse">
                  <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                  SYSTEM_FAULT: {error}
                </div>
              )}

              <ResultsDisplay
                output={output}
                searchParams={currentSearchParamsForResults}
                isLoading={isLoading}
                onQuestionClick={(q) => { setSearchParams({...searchParams, query: q}); executeSearch({...searchParams, query: q}); }}
                onAnalysisClick={() => {}}
                onSave={handleSaveResult}
                onRemoveSave={handleRemoveSave}
                isSaved={currentSearchParamsForResults ? isSearchBookmarked(currentSearchParamsForResults) : false}
                onJudgeClick={(name) => { setSelectedJudgeName(name); setShowJudgeModal(true); }}
              />
            </main>
          )}

          {activeTab === 'audit' && (
            <DocumentWorkspace 
              files={documentWorkspaceFiles}
              activeFileId={activeWorkspaceFileId}
              onSelectFile={setActiveWorkspaceFileId}
              onUpload={handleWorkspaceUpload}
              onRemove={handleRemoveWorkspaceFile}
              onMapNarrative={(file) => {
                // If the user wants narrative mapper, we'd need the base64 again, 
                // but for this UI, we just open a mapper or use the file object.
                setShowNarrativeMapper(true);
              }}
            />
          )}

          {activeTab === 'vault' && (
            <div className="lg:hidden animate-in slide-in-from-right duration-300">
               <Bookmarks 
                bookmarks={bookmarks}
                onView={handleViewBookmark}
                onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
              />
            </div>
          )}
        </div>
      </div>

      <footer className="mt-20 mb-8 lg:mb-0 text-center etched-label opacity-20 tracking-[0.4em] lg:tracking-[0.6em] px-4 text-[8px] lg:text-[10px]">
        PRECISION_LEGAL_ANALYSIS_NODE // GEMINI_v3_CORE
      </footer>

      {/* Mobile Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 lg:hidden bg-[#0a0a0a]/90 backdrop-blur-2xl border-t border-white/5 z-[60] pb-safe">
        <div className="flex justify-around items-center h-20 px-4">
          <button 
            onClick={() => setActiveTab('copilot')}
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'copilot' ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <HistoryIcon className="w-6 h-6" />
            <span className="text-[9px] font-black uppercase tracking-widest">Counsel</span>
          </button>

          <button 
            onClick={() => setActiveTab('audit')}
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'audit' ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <BrainCircuitIcon className="w-6 h-6" />
            <span className="text-[9px] font-black uppercase tracking-widest">Workspace</span>
          </button>

          <button 
            onClick={() => setActiveTab('vault')}
            className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'vault' ? 'text-blue-500' : 'text-slate-500'}`}
          >
            <BookmarkIcon className="w-6 h-6" />
            <span className="text-[9px] font-black uppercase tracking-widest">Vault</span>
          </button>
        </div>
      </nav>

      {showJudgeModal && selectedJudgeName && (
        <JudgeDetailModal judgeName={selectedJudgeName} onClose={() => setShowJudgeModal(false)} />
      )}

      {showCrossRefModal && (
        <CrossReferenceModal
          onClose={() => setShowCrossRefModal(false)}
          onReset={() => setCrossRefResult(null)}
          onAnalyze={async (a, am, an, b, bm, bn) => {
            setIsCrossRefLoading(true);
            try { setCrossRefResult(await crossReferenceDocuments(a, am, an, b, bm, bn)); }
            catch(e) { console.error(e); }
            finally { setIsCrossRefLoading(false); }
          }}
          result={crossRefResult}
          isLoading={isCrossRefLoading}
          error={null}
          onSave={(res) => {
            saveBookmark({
              key: generateCrossRefKey(res.fileAName, res.fileBName),
              type: 'cross_reference',
              result: res,
              savedAt: Date.now()
            });
            setBookmarks(getBookmarks());
          }}
          onRemoveSave={(r) => {
            removeBookmark(generateCrossRefKey(r.fileAName, r.fileBName));
            setBookmarks(getBookmarks());
          }}
          isSaved={crossRefResult ? isCrossRefBookmarked(crossRefResult.fileAName, crossRefResult.fileBName) : false}
        />
      )}
      {showNarrativeMapper && (
        <NarrativeMapper 
          onClose={() => { setShowNarrativeMapper(false); setNarrativeInitialData(null); }} 
          initialData={narrativeInitialData}
          onGenerate={async (b, m, n) => await generateNarrativeMap(b, m, n)}
        />
      )}
    </div>
  );
}

