const ResultsDisplay = ({ execSummary, briefing }: { execSummary?: string, briefing?: string }) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
    const [stopAudio, setStopAudio] = useState<(() => void) | null>(null);

    const playAudio = async (text: string) => {
        setIsGeneratingAudio(true);
        setIsPlaying(false); // Stop any previous audio
        setStopAudio(null);

        try {
            const base64Audio = await generateSpeech(text);
            if (base64Audio) {
                const stop = playAudioData(base64Audio);
                setStopAudio(stop);
                setIsPlaying(true);
            }
        } catch (error) {
            console.error("Error during audio generation or playback:", error);
            // Handle the error appropriately, e.g., display an error message
        } finally {
            setIsGeneratingAudio(false);
        }
    };
    const handleStop = () => {
        if (stopAudio) {
            stopAudio();
            setStopAudio(null);
            setIsPlaying(false);
        }
    };
    return (
        <div>
            {execSummary && (
                <div>
                    <h2>Executive Summary</h2>
                    <p>{execSummary}</p>
                    {isGeneratingAudio ? (
                        <SpinnerIcon />
                    ) : (
                        <button onClick={() => playAudio(execSummary)}>
