const SourceItem: React.FC<{ source: Source }> = ({ source }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    navigator.clipboard.writeText(source.uri);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex items-center justify-between p-4 bg-slate-950/40 border border-white/5 rounded hover:border-blue-500/30 transition-all group">
        <a href={source.uri} target="_blank" rel="noreferrer" className="flex-grow min-w-0 mr-4 group/link">
            <span className="text-xs font-medium text-slate-400 group-hover/link:text-white truncate block transition-colors">{source.title}</span>
            <span className="text-[9px] text-slate-600 truncate block mt-1 opacity-50 font-mono">{source.uri}</span>
        </a>
        <div className="flex items-center gap-3">
             <button 
                onClick={handleCopy}
                className="p-2 rounded-md hover:bg-white/5 text-slate-600 hover:text-white transition-colors relative"
                title="Copy Link"
             >
                {copied ? <CheckIcon className="w-3.5 h-3.5 text-green-500" /> : <ClipboardIcon className="w-3.5 h-3.5" />}
             </button>
             <a 
               href={source.uri} 
               target="_blank" 
               rel="noreferrer" 
               className="text-[10px] text-blue-500 font-bold opacity-0 group-hover:opacity-100 transition-all uppercase tracking-wider hidden sm:block"
             >
                View Record
             </a>
        </div>
    </div>
  );
};

