import { GoogleGenAI, GenerateContentResponse, Type, Modality } from "@google/genai";
import { type SearchParams, type SearchResult, type Source, TimelineEvent, JudgeSummary, JudgeDetail, DocumentAnalysisResult, CrossReferenceResult, NarrativeMapResult, AdversarialStrategy, StrategicTelemetry, DocumentAnnotation, SummaryLength } from '../types';

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable is not set.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const safeParseJSON = <T>(text: string | undefined): T | null => {
    if (!text) return null;
    let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    const start = Math.min(
      cleaned.indexOf('{') === -1 ? Infinity : cleaned.indexOf('{'),
      cleaned.indexOf('[') === -1 ? Infinity : cleaned.indexOf('[')
    );
    const end = Math.max(cleaned.lastIndexOf('}'), cleaned.lastIndexOf(']'));
    if (start !== Infinity && end !== -1) {
        cleaned = cleaned.substring(start, end + 1);
    }
    try {
        return JSON.parse(cleaned) as T;
    } catch (e) {
        return null;
    }
};

const buildPrompt = (params: SearchParams): string => {
  const { query, partyName, caseNumber, jurisdiction, summaryLength = SummaryLength.BALANCED } = params;

  let lengthInstruction = "";
  if (summaryLength === SummaryLength.CONCISE) {
    lengthInstruction = "PROVIDE A HIGH-LEVEL OVERVIEW. Focus only on the most critical procedural points and strategic impact. Keep the briefing brief and punchy.";
  } else if (summaryLength === SummaryLength.DETAILED) {
    lengthInstruction = "PROVIDE AN EXHAUSTIVE ANALYSIS. Include deep procedural nuances, potential case law references, comprehensive strategic breakdown, and detailed step-by-step guidance. Do not omit any relevant details.";
  } else {
    lengthInstruction = "PROVIDE A BALANCED BRIEFING. Ensure core procedural facts and tactical recommendations are clearly addressed without excessive verbosity.";
  }

  return `You are a Senior Legal Counselor for the Colorado Courts. You provide calm, intelligent, and authoritative guidance to self-represented individuals.

PROFESSIONAL OUTPUT GUIDELINES:
1. **AUTHORITATIVE TONE**: Speak as a world-class attorney—wise, protective, and precise.
2. **LEGAL BRIEF STRUCTURE**: Use formal headers (e.g., "Executive Counsel," "Procedural Analysis").
3. **CLARITY OVER JARGON**: Explain complex Colorado Rules of Civil Procedure (C.R.C.P.) in sophisticated but understandable terms.
4. **LOCAL SPECIFICITY**: Always ground your advice in Colorado law and Denver-specific court procedures.
5. **LENGTH CONSTRAINT**: ${lengthInstruction}

CONSULTATION REQUEST: "${query}"
${partyName ? `Party focus: ${partyName}` : ''}
${caseNumber ? `Case ID: ${caseNumber}` : ''}
${jurisdiction ? `Jurisdiction: ${jurisdiction}` : ''}

STRUCTURE YOUR RESPONSE:
# Legal Consultation Brief
## Summary of Strategic Position
## Procedural Considerations
## Recommended Actions (Formal list)
## Risks and Disclaimers`;
};

const generateStrategicTelemetry = async (query: string, summary: string): Promise<StrategicTelemetry> => {
    const prompt = `Analyze the following case profile and provide a formal Readiness Assessment and Risk Profile.
    Case Context: ${summary.substring(0, 2000)}

    Output JSON with:
    - readinessScore (0-100)
    - complexityIndex (1-10)
    - strategicFactors (Object: evidence, procedural, jurisdictional, resource, opponentVulnerability 1-10)
    - threatMatrix (Array of 5: label, impact 1-10, probability 1-10)`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
            }
        });
        return safeParseJSON<StrategicTelemetry>(response.text) || { 
          readinessScore: 50, 
          complexityIndex: 5, 
          threatMatrix: [],
          strategicFactors: { evidence: 5, procedural: 5, jurisdictional: 5, resource: 5, opponentVulnerability: 5 }
        };
    } catch {
        return { 
          readinessScore: 50, 
          complexityIndex: 5, 
          threatMatrix: [],
          strategicFactors: { evidence: 5, procedural: 5, jurisdictional: 5, resource: 5, opponentVulnerability: 5 }
        };
    }
};

const generateAdversarialStrategy = async (query: string, summary: string): Promise<AdversarialStrategy> => {
    const prompt = `Perform a formal Adversarial Analysis. Predict opposing counsel moves and propose strategic defensive counters.
    Context: ${summary.substring(0, 2000)}

    Output JSON: { prosecutorMoves: [], defenseCounters: [], hiddenRisks: [] } (3 items each)`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 8192 },
                responseMimeType: "application/json"
            }
        });
        return safeParseJSON<AdversarialStrategy>(response.text) || { prosecutorMoves: [], defenseCounters: [], hiddenRisks: [] };
    } catch {
        return { prosecutorMoves: [], defenseCounters: [], hiddenRisks: [] };
    }
}

export const generateExecutiveSummary = async (summary: string, strategy: AdversarialStrategy): Promise<string> => {
    const prompt = `Condense the following legal analysis into a ultra-concise Executive Summary (max 200 words).
    Highlight:
    1. Most critical finding.
    2. Primary tactical recommendation.
    3. High-level strategic outlook.

    Use a professional, calm, senior-partner tone.
    Context: ${summary}
    Strategy Context: ${JSON.stringify(strategy)}`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 4096 }
            }
        });
        return response.text || "Summary synthesis failure.";
    } catch {
        return "Executive brief synthesis interrupted.";
    }
};

const extractTimelineEvents = async (summary: string): Promise<TimelineEvent[]> => {
