const safeParseJSON = <T>(text: string | undefined): T | null => {
    if (!text) return null;
    let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    const start = Math.min(
      cleaned.indexOf('{') === -1 ? Infinity : cleaned.indexOf('{'),
      cleaned.indexOf('[') === -1 ? Infinity : cleaned.indexOf('[')
    );
    const end = Math.max(cleaned.lastIndexOf('}'), cleaned.lastIndexOf(']'));
    if (start !== Infinity && end !== -1) {
        cleaned = cleaned.substring(start, end + 1);
    }
    try {
        return JSON.parse(cleaned) as T;
    } catch (e) {
        return null;
    }
};

const buildPrompt = (params: SearchParams): string => {
  const { query, partyName, caseNumber, jurisdiction, summaryLength = SummaryLength.BALANCED } = params;

  let lengthInstruction = "";
  if (summaryLength === SummaryLength.CONCISE) {
    lengthInstruction = "PROVIDE A HIGH-LEVEL OVERVIEW. Focus only on the most critical procedural points and strategic impact. Keep the briefing brief and punchy.";
  } else if (summaryLength === SummaryLength.DETAILED) {
    lengthInstruction = "PROVIDE AN EXHAUSTIVE ANALYSIS. Include deep procedural nuances, potential case law references, comprehensive strategic breakdown, and detailed step-by-step guidance. Do not omit any relevant details.";
  } else {
    lengthInstruction = "PROVIDE A BALANCED BRIEFING. Ensure core procedural facts and tactical recommendations are clearly addressed without excessive verbosity.";
  }

  return `You are a Senior Legal Counselor for the Colorado Courts. You provide calm, intelligent, and authoritative guidance to self-represented individuals.

PROFESSIONAL OUTPUT GUIDELINES:
1. **AUTHORITATIVE TONE**: Speak as a world-class attorney—wise, protective, and precise.
2. **LEGAL BRIEF STRUCTURE**: Use formal headers (e.g., "Executive Counsel," "Procedural Analysis").
3. **CLARITY OVER JARGON**: Explain complex Colorado Rules of Civil Procedure (C.R.C.P.) in sophisticated but understandable terms.
4. **LOCAL SPECIFICITY**: Always ground your advice in Colorado law and Denver-specific court procedures.
5. **LENGTH CONSTRAINT**: ${lengthInstruction}

CONSULTATION REQUEST: "${query}"
${partyName ? `Party focus: ${partyName}` : ''}
${caseNumber ? `Case ID: ${caseNumber}` : ''}
${jurisdiction ? `Jurisdiction: ${jurisdiction}` : ''}

STRUCTURE YOUR RESPONSE:
# Legal Consultation Brief
## Summary of Strategic Position
## Procedural Considerations
## Recommended Actions (Formal list)
## Risks and Disclaimers`;
