const SourceItem: React.FC<{ source: Source }> = ({ source }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    navigator.clipboard.writeText(source.uri);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex items-center justify-between p-5 glass-slab !rounded-xl !bg-white/[0.02] border-white/5 hover:border-blue-500/30 transition-all group">
        <a href={source.uri} target="_blank" rel="noreferrer" className="flex-grow min-w-0 mr-4 group/link">
            <span className="text-xs font-bold text-slate-300 group-hover/link:text-blue-400 truncate block transition-colors">{source.title}</span>
            <span className="text-[9px] text-slate-600 truncate block mt-1 font-mono">{source.uri}</span>
        </a>
        <div className="flex items-center gap-3">
             <button 
                onClick={handleCopy}
                className="p-2.5 rounded-lg bg-white/5 text-slate-600 hover:text-white transition-all hover:scale-110 active:scale-95"
                title="Copy Link"
             >
                {copied ? <CheckIcon className="w-3.5 h-3.5 text-green-500" /> : <ClipboardIcon className="w-3.5 h-3.5" />}
             </button>
        </div>
    </div>
  );
};

