    - complexityIndex (1-10)
    - strategicFactors (Object: evidence, procedural, jurisdictional, resource, opponentVulnerability 1-10)
    - threatMatrix (Array of 5: label, impact 1-10, probability 1-10)`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
            }
        });
        return safeParseJSON<StrategicTelemetry>(response.text) || { 
          readinessScore: 50, 
          complexityIndex: 5, 
          threatMatrix: [],
          strategicFactors: { evidence: 5, procedural: 5, jurisdictional: 5, resource: 5, opponentVulnerability: 5 }
