const SourceItem: React.FC<{ source: Source }> = ({ source }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    navigator.clipboard.writeText(source.uri);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex items-center justify-between p-5 glass-slab !rounded-xl !bg-white/[0.02] border-white/5 hover:border-blue-500/30 transition-all group hover:!translate-y-[-2px] hover:!shadow-lg">
