                  <div className="h-px flex-grow mx-8 bg-white/5"></div>
               </div>
            </div>
          )}

          {/* Main Strategic Briefing Slab */}
          <div className="glass-slab p-8 lg:p-20 relative overflow-hidden">
            <div className="absolute -top-40 -right-40 w-96 h-96 bg-blue-600/5 blur-[120px] rounded-full pointer-events-none"></div>

            <div className="flex flex-col md:flex-row justify-between items-start border-b border-white/5 pb-12 mb-12 gap-8">
              <div className="space-y-4">
                <div className="flex items-center gap-3">
                  <span className="px-3 py-1 bg-white/5 rounded text-[8px] font-black text-slate-500 uppercase tracking-widest border border-white/5">Report_ID: {Math.random().toString(16).substring(2, 8)}</span>
                </div>
                <div className="flex flex-wrap items-center gap-8">
                    <h2 className="text-4xl lg:text-6xl font-bold text-white tracking-tight serif-heading leading-tight glow-text-blue">
                    Strategic Briefing
                    </h2>
                    <ReadAloudButton text={output.summary} />
                </div>
              </div>
            </div>

            <div className="prose prose-invert prose-xl max-w-none text-slate-300
              prose-h1:serif-heading prose-h1:text-white prose-h1:text-4xl prose-h1:mb-12
              prose-h2:serif-heading prose-h2:text-3xl prose-h2:text-blue-400 prose-h2:mt-16 prose-h2:mb-8 prose-h2:border-b prose-h2:border-white/10 prose-h2:pb-4 prose-h2:tracking-tight
              prose-h3:serif-heading prose-h3:text-2xl prose-h3:text-slate-100 prose-h3:mt-12 prose-h3:mb-6 prose-h3:italic
              prose-p:font-sans prose-p:leading-loose prose-p:font-light prose-p:text-lg lg:prose-p:text-xl prose-p:mb-10
              prose-strong:text-white prose-strong:font-bold
              prose-li:font-sans prose-li:text-slate-400 prose-li:text-lg prose-li:mb-4">
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            <StrategicTelemetryWidget telemetry={output.telemetry} isLoading={false} />
            <AdversarialStrategyWidget strategy={output.adversarialStrategy} isLoading={false} />
          </div>

          <div className="grid grid-cols-1 xl:grid-cols-2 gap-12">
            {output.identifiedJudges && output.identifiedJudges.length > 0 && (
              <IdentifiedJudges judges={output.identifiedJudges} isLoading={false} onJudgeClick={onJudgeClick} />
            )}
            <div className="glass-slab p-12 !bg-white/[0.01]">
              <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em] mb-10">Record_Verification_Sources</h4>
              <div className="space-y-4">
                {output.sources.map((s, i) => (
                   <SourceItem key={i} source={s} />
                ))}
              </div>
            </div>
          </div>

          {output.timelineEvents && output.timelineEvents.length > 0 && (
            <div className="glass-slab p-12 lg:p-20">
              <TimelineChart events={output.timelineEvents} isLoading={false} />
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
            <FollowUpQuestions questions={output.followUpQuestions || []} onQuestionClick={onQuestionClick} />
            <RelatedQueries queries={output.relatedQueries || []} onQueryClick={onQuestionClick} />
          </div>
        </div>
      ) : null}
    </div>
  );
}

import React, { useState, useCallback, useEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, type Bookmark, CaseType, Jurisdiction, type SearchResult, type DocumentAnalysisResult, type CrossReferenceResult, SummaryLength } from './types';
import { searchWebWithGemini, analyzeDocument, crossReferenceDocuments, generateNarrativeMap } from './services/geminiService';
import { getCachedResult, setCachedResult } from './services/cacheService';
import { addToHistory } from './services/historyService';
import { getBookmarks, saveBookmark, removeBookmark, isSearchBookmarked, isDocBookmarked, isCrossRefBookmarked, generateSearchKey, generateDocKey, generateCrossRefKey } from './services/bookmarkService';
import { MAX_QUERY_LENGTH } from './constants';
import Header from './components/Header';
import Banner from './components/Banner';
import SearchForm from './components/SearchForm';
import ResultsDisplay from './components/ResultsDisplay';
import Examples from './components/Examples';
import Bookmarks from './components/Bookmarks';
import JudgeDetailModal from './components/JudgeDetailModal';
import CrossReferenceModal from './components/CrossReferenceModal';
import NarrativeMapper from './components/NarrativeMapper';
import DocumentWorkspace from './components/DocumentWorkspace';
import ChatBot from './components/ChatBot';
import BrainCircuitIcon from './components/icons/BrainCircuitIcon';
import BookmarkIcon from './components/icons/BookmarkIcon';
import HistoryIcon from './components/icons/HistoryIcon';
import MessageIcon from './components/icons/MessageIcon';

type AppTab = 'copilot' | 'audit' | 'vault';

export default function App(): React.ReactNode {
  const [activeTab, setActiveTab] = useState<AppTab>('copilot');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [searchParams, setSearchParams] = useState<SearchParams>({
    query: '',
    searchType: SearchType.SEARCH,
    listCount: undefined,
    dateRange: DateRange.ANY,
    siteRestrict: '',
    fileType: '',
    partyName: '',
    caseNumber: '',
    caseStatus: CaseStatus.ALL,
    caseType: CaseType.ALL,
    jurisdiction: Jurisdiction.ALL,
    summaryLength: SummaryLength.BALANCED,
    deepThinking: false,
  });
  const [currentSearchParamsForResults, setCurrentSearchParamsForResults] = useState<SearchParams | null>(null);
  const [output, setOutput] = useState<SearchResult | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  const [showJudgeModal, setShowJudgeModal] = useState(false);
  const [selectedJudgeName, setSelectedJudgeName] = useState<string | null>(null);

  const [documentWorkspaceFiles, setDocumentWorkspaceFiles] = useState<DocumentAnalysisResult[]>([]);
  const [activeWorkspaceFileId, setActiveWorkspaceFileId] = useState<string | null>(null);

  const [showCrossRefModal, setShowCrossRefModal] = useState(false);
  const [crossRefResult, setCrossRefResult] = useState<CrossReferenceResult | null>(null);
  const [isCrossRefLoading, setIsCrossRefLoading] = useState(false);

  const [showNarrativeMapper, setShowNarrativeMapper] = useState(false);
  const [narrativeInitialData, setNarrativeInitialData] = useState<{b64: string, mime: string, name: string} | null>(null);

  useEffect(() => {
    setBookmarks(getBookmarks());
    const docBookmarks = getBookmarks().filter(b => b.type === 'document_analysis') as any[];
    if (docBookmarks.length > 0) {
      setDocumentWorkspaceFiles(docBookmarks.map(b => b.result));
    }
  }, []);

  const executeSearch = useCallback(async (params: SearchParams) => {
    const finalParams: SearchParams = { ...params, query: params.query.trim() };

    if (!finalParams.query) {
      setError('Please enter a valid legal inquiry.');
      return;
    }
    if (finalParams.query.length > MAX_QUERY_LENGTH) {
      setError(`Query exceeds character limit.`);
      return;
    }

    const cachedResult = getCachedResult(finalParams);
    if (cachedResult && !finalParams.deepThinking) {
      setOutput({
        ...cachedResult,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false,
      });
      setCurrentSearchParamsForResults(finalParams);
      setError(null);
      return;
    }

    setIsLoading(true);
    setError(null);
    setOutput({
      summary: '',
      sources: [],
      followUpQuestions: [],
      relatedQueries: [],
      timelineEvents: [],
      identifiedJudges: [],
      isSummaryStreaming: true,
      isFollowUpQuestionsLoading: false,
      isRelatedQueriesLoading: false,
      isTimelineLoading: false,
      isIdentifiedJudgesLoading: false,
    });
    setCurrentSearchParamsForResults(finalParams);

    try {
      const result = await searchWebWithGemini(finalParams, (partial) => {
        setOutput(prev => ({ ...prev!, ...partial }));
      });
      setOutput(prev => ({
          ...prev!,
          ...result,
          isSummaryStreaming: false,
      }));
      if (!finalParams.deepThinking) {
        setCachedResult(finalParams, result);
      }
      addToHistory(finalParams);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'System encountered an error during analysis.');
      setOutput(null);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleSearch = useCallback(() => executeSearch(searchParams), [searchParams, executeSearch]);

  const handleSaveResult = (params: SearchParams, result: SearchResult) => {
    const key = generateSearchKey(params);
    saveBookmark({ key, type: 'search', params, result, savedAt: Date.now() });
    setBookmarks(getBookmarks());
  };

  const handleRemoveSave = (params: SearchParams) => {
    removeBookmark(generateSearchKey(params));
    setBookmarks(getBookmarks());
  };

  const handleViewBookmark = (bookmark: Bookmark) => {
    if (bookmark.type === 'search') {
        setSearchParams(bookmark.params);
        setOutput({ ...bookmark.result, isSummaryStreaming: false });
        setCurrentSearchParamsForResults(bookmark.params);
        setActiveTab('copilot');
    } else if (bookmark.type === 'document_analysis') {
        setActiveWorkspaceFileId(bookmark.result.id || null);
        setActiveTab('audit');
    } else if (bookmark.type === 'cross_reference') {
        setCrossRefResult(bookmark.result);
        setShowCrossRefModal(true);
    }
  };

  const handleWorkspaceUpload = async (b64: string, mime: string, name: string) => {
    const tempId = crypto.randomUUID();
    const placeholder: DocumentAnalysisResult = {
      id: tempId,
      fileName: name,
      uploadDate: Date.now(),
      status: 'analyzing',
      strategicSummary: '',
      keyArguments: [],
      identifiedEntities: [],
      actionableInsights: []
    };
    setDocumentWorkspaceFiles(prev => [placeholder, ...prev]);
    setActiveWorkspaceFileId(tempId);

    try {
      const result = await analyzeDocument(b64, mime, name);
      setDocumentWorkspaceFiles(prev => prev.map(f => f.id === tempId ? { ...result, id: tempId } : f));
      saveBookmark({
        key: generateDocKey(name),
        type: 'document_analysis',
        result: { ...result, id: tempId },
        savedAt: Date.now()
      });
      setBookmarks(getBookmarks());
    } catch (e) {
      setDocumentWorkspaceFiles(prev => prev.map(f => f.id === tempId ? { ...f, status: 'error', strategicSummary: 'Audit failure.' } : f));
    }
  };

  const handleRemoveWorkspaceFile = (id: string) => {
    const file = documentWorkspaceFiles.find(f => f.id === id);
    if (file) {
      removeBookmark(generateDocKey(file.fileName));
      setBookmarks(getBookmarks());
    }
    setDocumentWorkspaceFiles(prev => prev.filter(f => f.id !== id));
    if (activeWorkspaceFileId === id) setActiveWorkspaceFileId(null);
  };

  // Resolve current active file for chat context
  const activeDocument = documentWorkspaceFiles.find(f => f.id === activeWorkspaceFileId);

  return (
    <div className="min-h-screen pb-24 lg:pb-12 flex flex-col bg-[#0f172a] text-slate-200 font-sans relative">
      <Banner />

      {/* Main Layout Container */}
      <div className="flex-grow flex flex-col lg:flex-row max-w-[1600px] mx-auto w-full px-4 lg:px-8 gap-8 mt-6 lg:mt-10">

        {/* Navigation Sidebar (Desktop) - Sticky */}
        <aside className="hidden lg:flex lg:w-72 flex-col gap-8 sticky top-6 h-[calc(100vh-3rem)] overflow-y-auto no-scrollbar py-2">
          <Header 
            onAnalyzeDocumentClick={() => setActiveTab('audit')} 
            onCrossReferenceClick={() => setShowCrossRefModal(true)} 
            onNarrativeMapperClick={() => setShowNarrativeMapper(true)}
            activeTab={activeTab}
          />
          <Bookmarks 
            bookmarks={bookmarks}
            onView={handleViewBookmark}
            onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
          />
        </aside>

        {/* Main Content Area */}
        <div className="flex-grow flex flex-col gap-8 min-w-0">
          {activeTab === 'copilot' && (
            <main className="flex flex-col gap-8 animate-in fade-in duration-500">
              <SearchForm
                params={searchParams}
                setParams={setSearchParams}
                onSearch={handleSearch}
                isLoading={isLoading}
                onClear={() => { setOutput(null); setSearchParams({...searchParams, query: ''}); }}
                onSelectHistory={(p) => { setSearchParams(p); executeSearch(p); }}
                onSave={() => currentSearchParamsForResults && output && handleSaveResult(currentSearchParamsForResults, output)}
                onImportPDF={() => setActiveTab('audit')}
                canSave={!!output && !!currentSearchParamsForResults}
              />

              <Examples onSelectExample={(ex) => setSearchParams({...searchParams, ...ex})} />

              {error && (
                <div className="bg-red-950/30 border border-red-900/50 p-4 rounded-lg flex items-center gap-3 text-red-400">
                  <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                  <span className="text-sm font-medium">System Alert: {error}</span>
                </div>
              )}

              <ResultsDisplay
                output={output}
                searchParams={currentSearchParamsForResults}
                isLoading={isLoading}
                onQuestionClick={(q) => { setSearchParams({...searchParams, query: q}); executeSearch({...searchParams, query: q}); }}
                onAnalysisClick={() => {}}
                onSave={handleSaveResult}
                onRemoveSave={handleRemoveSave}
                isSaved={currentSearchParamsForResults ? isSearchBookmarked(currentSearchParamsForResults) : false}
                onJudgeClick={(name) => { setSelectedJudgeName(name); setShowJudgeModal(true); }}
              />
            </main>
          )}

          {activeTab === 'audit' && (
            <DocumentWorkspace 
              files={documentWorkspaceFiles}
              activeFileId={activeWorkspaceFileId}
              onSelectFile={setActiveWorkspaceFileId}
              onUpload={handleWorkspaceUpload}
              onRemove={handleRemoveWorkspaceFile}
              onMapNarrative={(file) => setShowNarrativeMapper(true)}
            />
          )}

          {activeTab === 'vault' && (
            <div className="lg:hidden animate-in slide-in-from-right duration-300">
               <Bookmarks 
                bookmarks={bookmarks}
                onView={handleViewBookmark}
                onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
              />
            </div>
          )}
        </div>
      </div>

      <footer className="mt-20 py-8 text-center text-slate-500 text-[10px] uppercase tracking-widest border-t border-slate-800">
        Colorado Court Counsel // Licensed for Legal Professionals
      </footer>

      {/* Floating Chat Trigger */}
      <button 
        onClick={() => setIsChatOpen(true)}
        className="fixed bottom-24 lg:bottom-8 right-8 z-[100] w-16 h-16 bg-blue-600 hover:bg-blue-500 text-white rounded-full shadow-[0_0_20px_rgba(37,99,235,0.4)] flex items-center justify-center transition-all hover:scale-110 active:scale-95 group"
      >
        <MessageIcon className="w-7 h-7" />
        <div className="absolute -top-1 -right-1 bg-red-500 w-4 h-4 rounded-full border-2 border-[#0f172a] group-hover:animate-ping"></div>
      </button>

      {/* Integrated Context-Aware Chat Window */}
      {isChatOpen && (
        <ChatBot 
            onClose={() => setIsChatOpen(false)} 
            contextResult={output}
            contextDocument={activeDocument}
        />
      )}

      {/* Mobile Nav */}
      <nav className="fixed bottom-0 left-0 right-0 lg:hidden bg-[#0f172a]/95 backdrop-blur-lg border-t border-slate-700 z-[60] pb-safe">
        <div className="flex justify-around items-center h-16">
          <button onClick={() => setActiveTab('copilot')} className={`${activeTab === 'copilot' ? 'text-blue-500' : 'text-slate-500'} flex flex-col items-center gap-1`}>
            <HistoryIcon className="w-5 h-5" />
            <span className="text-[10px] font-semibold">Counsel</span>
          </button>
          <button onClick={() => setActiveTab('audit')} className={`${activeTab === 'audit' ? 'text-blue-500' : 'text-slate-500'} flex flex-col items-center gap-1`}>
            <BrainCircuitIcon className="w-5 h-5" />
            <span className="text-[10px] font-semibold">Workspace</span>
          </button>
          <button onClick={() => setActiveTab('vault')} className={`${activeTab === 'vault' ? 'text-blue-500' : 'text-slate-500'} flex flex-col items-center gap-1`}>
            <BookmarkIcon className="w-5 h-5" />
            <span className="text-[10px] font-semibold">Vault</span>
          </button>
        </div>
      </nav>

      {showJudgeModal && selectedJudgeName && (
        <JudgeDetailModal judgeName={selectedJudgeName} onClose={() => setShowJudgeModal(false)} />
      )}
      {showCrossRefModal && (
        <CrossReferenceModal
          onClose={() => setShowCrossRefModal(false)}
          onReset={() => setCrossRefResult(null)}
          onAnalyze={async (a, am, an, b, bm, bn) => {
            setIsCrossRefLoading(true);
            try { setCrossRefResult(await crossReferenceDocuments(a, am, an, b, bm, bn)); }
            catch(e) { console.error(e); }
            finally { setIsCrossRefLoading(false); }
          }}
          result={crossRefResult}
          isLoading={isCrossRefLoading}
          error={null}
          onSave={(res) => {
            saveBookmark({ key: generateCrossRefKey(res.fileAName, res.fileBName), type: 'cross_reference', result: res, savedAt: Date.now() });
            setBookmarks(getBookmarks());
          }}
          onRemoveSave={(r) => {
            removeBookmark(generateCrossRefKey(r.fileAName, r.fileBName));
            setBookmarks(getBookmarks());
          }}
          isSaved={crossRefResult ? isCrossRefBookmarked(crossRefResult.fileAName, crossRefResult.fileBName) : false}
        />
      )}
      {showNarrativeMapper && (
        <NarrativeMapper 
          onClose={() => { setShowNarrativeMapper(false); setNarrativeInitialData(null); }} 
          initialData={narrativeInitialData}
          onGenerate={async (b, m, n) => await generateNarrativeMap(b, m, n)}
        />
      )}
    </div>
  );
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { type ChatMessage, type SearchResult, type DocumentAnalysisResult } from '../types';
import { conductTacticalChat } from '../services/geminiService';
import CloseIcon from './icons/CloseIcon';
import SpinnerIcon from './icons/SpinnerIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import MessageIcon from './icons/MessageIcon';

interface ChatBotProps {
  onClose: () => void;
  contextResult?: SearchResult | null;
  contextDocument?: DocumentAnalysisResult | null;
}

export default function ChatBot({ onClose, contextResult, contextDocument }: ChatBotProps): React.ReactNode {
  // Determine if we have context
  const hasResultContext = !!(contextResult && contextResult.summary);
  const hasDocumentContext = !!(contextDocument && contextDocument.strategicSummary);
  const isContextLinked = hasResultContext || hasDocumentContext;

  const initialGreeting = useMemo(() => {
    if (hasDocumentContext) return `Neural link to dossier [${contextDocument.fileName}] established. Tactical audit complete. How should we exploit the identified discrepancies?`;
    if (hasResultContext) return "Intelligence dossier active in neural workspace. Tactical scenario mapped. What offensive maneuvers do you require?";
    return "Strategic Tactical Hub established. I am ready to identify institutional failure points. Provide a scenario.";
  }, []);

  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: initialGreeting }
  ]);
  const [input, setInput] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Auto-scroll on new messages
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isStreaming]);

  // Construct a tactical context prompt
  const currentContextString = useMemo(() => {
    if (!isContextLinked) return "";
    let ctx = "CURRENT TACTICAL CONTEXT:\n";
    if (hasDocumentContext) {
      ctx += `Document: ${contextDocument.fileName}\nAudit Summary: ${contextDocument.strategicSummary}\nKey Arguments: ${contextDocument.keyArguments.join('; ')}`;
    } else if (hasResultContext) {
      ctx += `Search Dossier Summary: ${contextResult.summary}\n`;
    }
    return ctx;
  }, [contextResult, contextDocument, isContextLinked]);

  const handleSend = async () => {
    if (!input.trim() || isStreaming) return;

    const userMsg = input.trim();
    setInput('');

    // Add user message to local history
    const nextHistory = [...messages, { role: 'user', text: userMsg } as ChatMessage];
    setMessages(nextHistory);
    setIsStreaming(true);

    try {
      let streamingText = "";
      // Placeholder for AI thinking
      setMessages(prev => [...prev, { role: 'model', text: "", isThinking: true }]);

      // Pass the current context to the chat service
      await conductTacticalChat(messages, userMsg, (chunk) => {
        streamingText += chunk;
        setMessages(prev => {
          const updated = [...prev];
          const last = updated[updated.length - 1];
          if (last.role === 'model') {
            last.text = streamingText;
            last.isThinking = false;
          }
          return updated;
        });
      }, currentContextString);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "Neural uplink severed. Institutional gravity detected. Re-establish connection." }]);
    } finally {
      setIsStreaming(false);
    }
  };

  return (
    <div className="fixed inset-0 lg:inset-auto lg:bottom-28 lg:right-8 lg:w-[450px] lg:h-[700px] z-[200] flex flex-col glass-slab shadow-[0_50px_100px_rgba(0,0,0,0.6)] animate-in slide-in-from-bottom-8 duration-500 overflow-hidden">

      {/* Header HUD */}
      <div className="px-6 py-5 border-b border-white/5 bg-slate-800/50 flex justify-between items-center shrink-0">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-blue-600 rounded-lg shadow-[0_0_15px_rgba(37,99,235,0.4)]">
             <BrainCircuitIcon className="w-5 h-5 text-white" />
          </div>
          <div>
            <h3 className="text-sm font-black text-white uppercase tracking-widest italic leading-none">Tactical_Nexus</h3>
            <div className="flex items-center gap-2 mt-1">
                <span className={`w-1.5 h-1.5 rounded-full ${isContextLinked ? 'bg-emerald-500 shadow-[0_0_8px_#10b981]' : 'bg-slate-600'}`}></span>
                <span className="text-[9px] font-mono text-blue-400 uppercase tracking-tighter">
                    {hasDocumentContext ? `Link: ${contextDocument.fileName.substring(0, 15)}...` : 
                     hasResultContext ? 'Link: Dossier_Intel' : 'Standard_Uplink'}
                </span>
            </div>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-slate-500 hover:text-white transition-colors">
          <CloseIcon className="w-6 h-6" />
        </button>
      </div>

      {/* Messages */}
      <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-8 custom-scrollbar bg-[#0f172a]/40">
        {messages.map((msg, i) => (
          <div key={i} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div className={`text-[8px] font-black uppercase tracking-widest mb-2 ${msg.role === 'user' ? 'text-blue-500' : 'text-slate-500'}`}>
              {msg.role === 'user' ? 'Operator' : 'Strategic_Intel'}
            </div>
            <div className={`p-4 lg:p-5 rounded-2xl max-w-[90%] ${
              msg.role === 'user' 
                ? 'bg-blue-600/10 border border-blue-500/30 text-blue-100' 
                : 'bg-white/[0.03] border border-white/5 text-slate-200 shadow-xl'
            }`}>
              {msg.isThinking ? (
                <div className="flex items-center gap-4">
                   <SpinnerIcon className="w-4 h-4 text-blue-500" />
                   <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] animate-pulse">Calculating_Asymmetry...</span>
                </div>
              ) : (
                <div className="prose prose-invert prose-sm max-w-none text-slate-200 prose-p:leading-relaxed prose-strong:text-blue-400 prose-h2:text-blue-500 prose-h2:text-xs prose-h2:uppercase">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{msg.text}</ReactMarkdown>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Input Module */}
