    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: finalSystemInstruction,
      thinkingConfig: { thinkingBudget: 32768 }
    },
    history: history.map(m => ({ role: m.role, parts: [{ text: m.text }] }))
