        },
        history: history.map(h => ({
            role: h.role,
            parts: [{ text: h.text }]
        }))
    });

    const response = await chat.sendMessageStream({ message: newMessage });

    for await (const chunk of response) {
        const text = chunk.text;
        if (text) onStream(text);
    }
};

