let audioContext: AudioContext | null = null;

function getAudioContext() {
    if (!audioContext) {
        audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
    }
    return audioContext;
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const generateSpeech = async (text: string): Promise<string | null> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });
        return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) {
        console.error("Audio generation failed", e);
        return null;
    }
};

export const playAudioData = async (base64String: string, onEnded?: () => void): Promise<() => void> => {
    const ctx = getAudioContext();
    if (ctx.state === 'suspended') {
        await ctx.resume();
    }

    const audioBuffer = await decodeAudioData(decode(base64String), ctx, 24000, 1);

    const source = ctx.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(ctx.destination);
    source.onended = () => {
        if (onEnded) onEnded();
    };
    source.start();

    return () => {
        try {
            source.stop();
            source.disconnect();
        } catch (e) {}
    };
};

// Implemented conductTacticalChat to support AI chat interaction with contextual awareness
export const conductTacticalChat = async (
    history: ChatMessage[],
    message: string,
    onPartial: (chunk: string) => void,
    context?: string
) => {
    // Map existing history to the format required by the GenAI SDK
    const contents = history.map(msg => ({
        role: msg.role,
        parts: [{ text: msg.text }]
    }));

    // Inject contextual metadata into the user's current query for synchronized awareness
    const userMessageText = context ? `${context}\n\nOPERATOR_QUERY: ${message}` : message;

    contents.push({
        role: 'user',
        parts: [{ text: userMessageText }]
    });

    const response = await ai.models.generateContentStream({
        model: 'gemini-3-pro-preview', // High-tier reasoning for strategic tactical maneuvers
        contents,
        config: {
            systemInstruction: LEGAL_TACTICIAN_IDENTITY,
            thinkingConfig: { thinkingBudget: 0 } // Disable thinking for stream to maintain real-time responsiveness
        },
    });

    for await (const chunk of response) {
        onPartial(chunk.text || '');
    }
};

