export const searchWebWithGemini = async (params: SearchParams, onPartial: (partial: any) => void): Promise<SearchResult> => {
    const isDBFetch = params.enableExternalDB && params.caseNumber;
    const prompt = isDBFetch ? buildDatabaseFetchPrompt(params) : buildPrompt(params);

    // Config: Use different thinking budgets based on mode
    // External DB fetch might need deep thinking to construct a realistic timeline if data is missing, 
    // or to parse complex search results.
    const thinkingBudget = (params.deepThinking || isDBFetch) ? 32768 : 0;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
            tools: [{ googleSearch: {} }],
            thinkingConfig: { thinkingBudget },
            systemInstruction: LEGAL_TACTICIAN_IDENTITY
        }
    });

    const summary = response.text || "No intelligence harvested.";
    const sources: Source[] = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
        uri: chunk.web?.uri || '',
        title: chunk.web?.title || 'Grounding Reference'
    })).filter((s: any) => s.uri) || [];

    onPartial({ summary, sources });

    const [telemetry, adversarial, timeline, judges] = await Promise.all([
        generateStrategicTelemetry(params.query, summary),
        generateAdversarialStrategy(params.query, summary),
        extractTimelineEvents(summary),
        extractJudges(summary)
    ]);

    return {
        summary,
        sources,
        telemetry,
        adversarialStrategy: adversarial,
        timelineEvents: timeline,
        identifiedJudges: judges,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false
    };
};

